operations.replace:
button.addEventListener("click", event => {
  event.preventDefault();
  event.stopImmediatePropagation();

  const foundrySidebar =
    globalThis.ui?.sidebar ??
    null;

  if (
    frameConnSidebarActive &&
    foundrySidebar?.expanded !== false &&
    typeof foundrySidebar?.collapse === "function"
  ) {
    foundrySidebar.collapse();
    return;
  }

  void openFrameConnSidebarPresentation();
}, true);

#sidebar .frame-conn-sidebar-tab-button i {
  pointer-events: none;
}

#sidebar .frame-conn-sidebar-tab-slot::before,
#sidebar .frame-conn-sidebar-tab-slot::after,
#sidebar .frame-conn-sidebar-tab-button::before,
#sidebar .frame-conn-sidebar-tab-button::after {
  display: none !important;
  content: none !important;
}
